### Throttle decorator

class _ThrottleState:
    def __init__(self, interval, max_calls=None):
        self.interval = interval  # timedelta or float seconds
        self.max_calls = max_calls
        self.calls = []
        self.lock = threading.Lock()

    def _normalize_interval(self, interval):
        """Normalize interval to seconds (float)."""
        if isinstance(interval, timedelta):
            return interval.total_seconds()
        return interval

    def _cleanup_old_calls(self, now):
        """Remove calls older than interval."""
        interval_secs = self._normalize_interval(self.interval)
        cutoff = now - interval_secs
        self.calls = [t for t in self.calls if t > cutoff]

    def can_call(self):
        with self.lock:
            now = time.time()
            self._cleanup_old_calls(now)

            if self.max_calls is not None and len(self.calls) >= self.max_calls:
                return False

            self.calls.append(now)
            return True


def throttle(interval, max_calls=None):
    """Decorator that limits how frequently a function can be called.

    Args:
        interval: Time between allowed calls (float seconds or timedelta)
        max_calls: Maximum number of calls allowed within the interval (optional)
    """
    def decorator(func):
        state = _ThrottleState(interval, max_calls)

        @wraps(func)
        def wrapper(*args, **kwargs):
            if state.can_call():
                return func(*args, **kwargs)
            else:
                raise RuntimeError(
                    f"Function {func.__name__} is being called too frequently. "
                    f"Rate limit: {interval}s interval, max {max_calls or 'unlimited'} calls."
                )
        return wrapper
    return decorator


def process_beat(func=None, beat=None):
    """Decorator that throttles a function to run at most once per beat interval.

    Alias for throttle with semantic name.
    """
    if func is not None:
        # Called as @process_beat without parentheses
        return throttle(beat)(func)
    elif beat is not None:
        # Called as @process_beat(beat)
        return throttle(beat)
    else:
        # Called as @process_beat()
        return throttle


def api_call(func=None, retry_count=3, errors=Exception, timeout=1):
    """Decorator that wraps a function as an API call with automatic retries.

    Combines retry logic with fallback capability.
    """
    def decorator(f):
        @retry(tries=retry_count, errors=errors, timeout=lambda _: timeout)
        @wraps(f)
        def wrapper(*args, **kwargs):
            return f(*args, **kwargs)
        return wrapper

    if func is not None:
        return decorator(func)
    return decorator


